import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
from torch.nn.modules.utils import _triple

CPP_SRC = r"""
#include <torch/extension.h>
at::Tensor conv3d_forward(at::Tensor input, at::Tensor weight, at::Tensor bias,
                          int64_t stride, int64_t padding, int64_t dilation, int64_t groups);
"""

CUDA_SRC = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

#define TILE_X 8
#define TILE_Y 8
#define TILE_Z 8
#define OC_BLOCK 8
#define OC_LANES 4
#define DIRECT_THREADS 256

__global__ void conv3d_fwd_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int Cin, int D, int H, int W,
    int Cout, int K, int Dout, int Hout, int Wout,
    int stride, int pad, int dilation, int groups,
    int has_bias, int use_shared,
    int in_sh_elems, int w_sh_elems,
    int x_tiles, int y_tiles, int z_tiles, int oc_blocks,
    long long total_outputs)
{
    if (!use_shared) {
        long long tid = (long long)blockIdx.x * blockDim.x + threadIdx.x;
        long long step = (long long)gridDim.x * blockDim.x;
        int Cg = Cin / groups;
        int ocpg = Cout / groups;
        for (long long idx = tid; idx < total_outputs; idx += step) {
            long long t = idx;
            int ox = (int)(t % Wout); t /= Wout;
            int oy = (int)(t % Hout); t /= Hout;
            int oz = (int)(t % Dout); t /= Dout;
            int oc = (int)(t % Cout); t /= Cout;
            int n = (int)t;

            int g = oc / ocpg;
            int cbase = g * Cg;
            float acc = has_bias ? bias[oc] : 0.0f;
            for (int c = 0; c < Cg; ++c) {
                int ci = cbase + c;
                for (int kz = 0; kz < K; ++kz) {
                    int iz = oz * stride - pad + kz * dilation;
                    if (iz < 0 || iz >= D) continue;
                    for (int ky = 0; ky < K; ++ky) {
                        int iy = oy * stride - pad + ky * dilation;
                        if (iy < 0 || iy >= H) continue;
                        for (int kx = 0; kx < K; ++kx) {
                            int ix = ox * stride - pad + kx * dilation;
                            if (ix < 0 || ix >= W) continue;
                            long long in_idx = (((long long)(n * Cin + ci) * D + iz) * H + iy) * W + ix;
                            long long w_idx = (((long long)(oc * Cg + c) * K + kz) * K + ky) * K + kx;
                            acc += input[in_idx] * weight[w_idx];
                        }
                    }
                }
            }
            output[idx] = acc;
        }
        return;
    }

    extern __shared__ float smem[];
    float* s_in = smem;
    float* s_w = smem + in_sh_elems;

    int Cg = Cin / groups;
    int ocpg = Cout / groups;

    int xtile = blockIdx.x;
    int ytile = blockIdx.y;
    int zb = blockIdx.z;
    int ztile = zb % z_tiles;
    int tmp = zb / z_tiles;
    int ocb = tmp % oc_blocks;
    int n = tmp / oc_blocks;

    int ox0 = xtile * TILE_X;
    int oy0 = ytile * TILE_Y;
    int oz0 = ztile * TILE_Z;
    int oc0 = ocb * OC_BLOCK;

    int sx = (TILE_X - 1) * stride + (K - 1) * dilation + 1;
    int sy = (TILE_Y - 1) * stride + (K - 1) * dilation + 1;
    int sz = (TILE_Z - 1) * stride + (K - 1) * dilation + 1;

    int in_x0 = ox0 * stride - pad;
    int in_y0 = oy0 * stride - pad;
    int in_z0 = oz0 * stride - pad;

    int g = oc0 / ocpg;
    int cbase = g * Cg;

    int tid = (threadIdx.z * blockDim.y + threadIdx.y) * blockDim.x + threadIdx.x;
    int nthreads = blockDim.x * blockDim.y * blockDim.z;

    int in_total = Cg * sz * sy * sx;
    for (int i = tid; i < in_total; i += nthreads) {
        int lox = i % sx;
        int t = i / sx;
        int loy = t % sy;
        t /= sy;
        int loz = t % sz;
        int c = t / sz;

        int ix = in_x0 + lox;
        int iy = in_y0 + loy;
        int iz = in_z0 + loz;
        float v = 0.0f;
        if (ix >= 0 && ix < W && iy >= 0 && iy < H && iz >= 0 && iz < D) {
            int ci = cbase + c;
            long long in_idx = (((long long)(n * Cin + ci) * D + iz) * H + iy) * W + ix;
            v = input[in_idx];
        }
        s_in[i] = v;
    }

    int w_total = OC_BLOCK * Cg * K * K * K;
    for (int i = tid; i < w_total; i += nthreads) {
        int kx = i % K;
        int t = i / K;
        int ky = t % K;
        t /= K;
        int kz = t % K;
        t /= K;
        int c = t % Cg;
        int ocl = t / Cg;
        int oc = oc0 + ocl;
        float v = 0.0f;
        if (oc < Cout) {
            long long w_idx = (((long long)(oc * Cg + c) * K + kz) * K + ky) * K + kx;
            v = weight[w_idx];
        }
        s_w[i] = v;
    }
    __syncthreads();

    int lx = threadIdx.x;
    int ly = threadIdx.y;
    int oc_lane = threadIdx.z;
    int ox = ox0 + lx;
    int oy = oy0 + ly;

    for (int lz = 0; lz < TILE_Z; ++lz) {
        int oz = oz0 + lz;
        if (oz >= Dout) continue;
        #pragma unroll
        for (int oc_off = 0; oc_off < OC_BLOCK; oc_off += OC_LANES) {
            int ocl = oc_lane + oc_off;
            int oc = oc0 + ocl;
            if (oc >= Cout || ox >= Wout || oy >= Hout) continue;

            float acc = has_bias ? bias[oc] : 0.0f;
            int base_z = lz * stride;
            int base_y = ly * stride;
            int base_x = lx * stride;

            for (int c = 0; c < Cg; ++c) {
                for (int kz = 0; kz < K; ++kz) {
                    int sz_i = base_z + kz * dilation;
                    for (int ky = 0; ky < K; ++ky) {
                        int sy_i = base_y + ky * dilation;
                        int in_row = ((c * sz + sz_i) * sy + sy_i) * sx;
                        int w_row = (((ocl * Cg + c) * K + kz) * K + ky) * K;
                        for (int kx = 0; kx < K; ++kx) {
                            int sx_i = base_x + kx * dilation;
                            acc += s_in[in_row + sx_i] * s_w[w_row + kx];
                        }
                    }
                }
            }
            long long out_idx = (((long long)(n * Cout + oc) * Dout + oz) * Hout + oy) * Wout + ox;
            output[out_idx] = acc;
        }
    }
}

at::Tensor conv3d_forward(at::Tensor input, at::Tensor weight, at::Tensor bias,
                          int64_t stride_, int64_t padding_, int64_t dilation_, int64_t groups_) {
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(input.scalar_type() == at::kFloat, "input must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    TORCH_CHECK(input.dim() == 5, "input must be NCDHW");
    TORCH_CHECK(weight.dim() == 5, "weight must be Cout,Cin/groups,K,K,K");

    auto x = input.contiguous();
    auto w = weight.contiguous();

    int64_t N = x.size(0), Cin = x.size(1), D = x.size(2), H = x.size(3), W = x.size(4);
    int64_t Cout = w.size(0), Cg = w.size(1), K = w.size(2);
    int64_t stride = stride_, pad = padding_, dilation = dilation_, groups = groups_;

    TORCH_CHECK(w.size(3) == K && w.size(4) == K, "kernel must be cubic");
    TORCH_CHECK(Cin % groups == 0, "in_channels must be divisible by groups");
